class AVACalcSalesQuotationLineHKFactor    extends AVACalcSalesQuotationLine
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_dataContract">_contract</param>
public void processOperation(AVACalcSalesQuotationLineHKFactorContract     _dataContract)
{
    AVACalcSalesQuotationLineHKFactorContract contract = _datacontract;
    QuotationId                            quotationId = contract.parmQuotationId();
    //Factor                                 factor      = contract.parmFactor();
    AVAFactor                                 factor      = contract.parmFactor();
    SalesPrice                             newSalesPrice;

    while select salesQuotationLine
        where salesQuotationLine.QuotationId == quotationId
    {
        newSalesPrice = salesQuotationLine.AVAHKQuotCurrency * factor;
        newSalesPrice = decRound(newSalesPrice, 2);
        if (newSalesPrice  > salesQuotationLine.AVABestPrice)
        {
            salesQuotationLine.SalesPrice = salesQuotationLine.AVABestPrice;
        }
        else
        {
            salesQuotationLine.SalesPrice = newSalesPrice;
        }

        this.updateQuotationLineFields();
        ttsbegin;
        salesQuotationLine.selectForUpdate(true);
        salesQuotationLine.doUpdate();
        ttscommit;
    }

    this.updateLVPostion(quotationId);

}
